import{_ as e,H as t,f as E,i as a}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"01 | 编程环境：工欲善其事，必先利其器","description":"","frontmatter":{},"headers":[{"level":2,"title":"C++ 编程环境搭建","slug":"c-编程环境搭建","link":"#c-编程环境搭建","children":[]},{"level":2,"title":"创建最基本的能运行的 C++ 程序","slug":"创建最基本的能运行的-c-程序","link":"#创建最基本的能运行的-c-程序","children":[]},{"level":2,"title":"Visual Studio 中程序的调试方法","slug":"visual-studio-中程序的调试方法","link":"#visual-studio-中程序的调试方法","children":[]},{"level":2,"title":"普通的断点调试（跟踪调试）","slug":"普通的断点调试-跟踪调试","link":"#普通的断点调试-跟踪调试","children":[]},{"level":2,"title":"学会调试时查看内存中的内容","slug":"学会调试时查看内存中的内容","link":"#学会调试时查看内存中的内容","children":[]},{"level":2,"title":"快速监视窗口","slug":"快速监视窗口","link":"#快速监视窗口","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"归纳思考","slug":"归纳思考","link":"#归纳思考","children":[]}],"relativePath":"快速上手C++数据结构与算法/01｜编程环境：工欲善其事，必先利其器.md","filePath":"快速上手C++数据结构与算法/01｜编程环境：工欲善其事，必先利其器.md","lastUpdated":1795557152000}'),s={name:"快速上手C++数据结构与算法/01｜编程环境：工欲善其事，必先利其器.md"};function l(B,i,n,o,p,u){return t(),E("div",null,[...i[0]||(i[0]=[a(`<h1 id="_01-编程环境-工欲善其事-必先利其器" tabindex="-1">01 | 编程环境：工欲善其事，必先利其器 <a class="header-anchor" href="#_01-编程环境-工欲善其事-必先利其器" aria-label="Permalink to &quot;01 | 编程环境：工欲善其事，必先利其器&quot;">​</a></h1><p>你好，我是王健伟。</p><p>俗话说，“工欲善其事，必先利其器”，今天我们就来说说编程环境的搭建。</p><p>搭建一个良好的编程环境对于后续的学习非常重要，所谓好的编程环境，是指这个编程环境易学，易用，让使用者很少出错，即便出现错误也能根据一些信息快速定位出错的位置。</p><p>偶尔会听到有人建议开发者用纯记事本写程序而不采用任何编程环境，通过这样的方式锻炼自己编写程序的能力。这种说法是令人匪夷所思的！</p><p>这节课，我们就从 C++ 编程环境的搭建，创建最基本的能运行的 C++ 程序以及 Visual Studio中程序的调试方法这几个方面，帮助你快速搞定一个 C++ 语言的编程环境，让后续的学习更加便捷、高效。</p><h2 id="c-编程环境搭建" tabindex="-1">C++ 编程环境搭建 <a class="header-anchor" href="#c-编程环境搭建" aria-label="Permalink to &quot;C++ 编程环境搭建&quot;">​</a></h2><p>咱们这门课所展示的各种范例，会在 Windows 操作系统平台上进行演示。对于演示环境的要求不高，我一般使用 Visual Studio，版本上不建议使用比 Visual Studio 2005 更老的版本，以免在太老的开发环境下出现某些范例无法成功演示的窘境。注意，能使用高版本，尽量不使用低版本。</p><p>这门课程采用的演示环境是 Visual Studio 2022 集成开发环境。该环境使用简单，调试方便，这意味着讲解和演示会变得特别方便，同时也能大大降低你对一些复杂知识的理解难度。</p><p>为了让你顺利地开始学习，在这里将详细地阐述一下 Visual Studio 2022 的安装过程（在线安装，需要网络支持）。</p><p>Visual Studio 2022 是目前微软公司推出的最新版本集成开发环境，可以直接访问网站。这个页面就有 Visual Studio 2022 的下载，分为三个版本：社区版（Community）、专业版（Professional）、企业版（Enterprise）。其中社区版是可以免费使用的，下载社区版即可。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/1.png" alt=""></a></p><ul><li>图1 Visual Studio 2012可供下载的三个版本</li></ul><p>在图 1 中单击 Community 2022，此时会将一个大概 2MB 的可执行文件下载到自己的电脑上，这个可执行文件实际是个下载器，运行该下载器，它会按步骤提示下载和安装 VisualStudio 2022。</p><p>这种安装方式属于在线下载和安装，整个过程可能会持续半小时到数小时之间，安装时长主要取决于网速和计算机速度。</p><p>安装过程中会出现选择框，让用户选择安装哪些组件，如图 2 所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/2.png" alt=""></a></p><ul><li>图2 Visual Studio 2022安装选项</li></ul><p>这里只选择“使用 C++ 的桌面开发”以及“通用 Windows 平台开发”，在选择这两个选项时，安装界面右侧会出现额外的安装详细信息，里面有很多可以勾选的项，保持默认，不做进一步勾选。</p><p>请记住一个原则：只安装看上去和 C++ 开发有关的选项，即便错过了一些选项，以后可以重复这个步骤补充安装，但切不可图省事而完全安装，因为那可能会耗费数十甚至上百 GB 的磁盘空间，完全没有必要。</p><p>在图 2 左侧靠下的“位置”处，可以单击“更改”，尽量把安装位置设置到非 C 盘（非系统盘）的位置以尽量减少对系统盘空间的耗费，系统盘空间非常宝贵，一旦空间耗尽可能会导致计算机运行变慢甚至崩溃等各种问题。这一点也请切记！</p><p>安装完成后，很可能在计算机的桌面上看不到 Visual Studio 2022 程序图标，此时必须到操作系统左下角，单击“开始”按钮，然后往下翻，一直找到 Visual Studio 2022 图标，如图 3 所示，用鼠标单击并按住图形部分拖动到桌面上以创建桌面快捷方式，下次双击桌面上的该图标即可运行 Visual Studio 2022。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/3.png" alt=""></a></p><ul><li>图3 开始菜单中的Visual Studio 2022运行图标</li></ul><p>双击 Visual Studio 2022 图标以运行 Visual Studio 2022，启动界面如图 4 所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/4.png" alt=""></a></p><ul><li>图4 Visual Studio 2022启动界面</li></ul><p>单击图 4 的右下角的“继续但无需代码”链接直接进入到开发环境中，因为这是个集成开发环境，可以开发很多种计算机编程语言所编写的代码，所以第一步先设置开发环境为 C++ 语言，在开发环境中，进行这样几步操作。</p><ol><li><p>选择菜单“工具、导入和导出设置”命令；</p></li><li><p>在弹出的对话框中，选择最下面的“重置所有设置”选项并单击“下一步”按钮；</p></li><li><p>选择下面的“否，仅重置设置，从而覆盖当前设置”项并单击“下一步”按钮；</p></li><li><p>选择“Visual C++”选项并单击“完成”按钮。</p></li></ol><p>等待数秒时间，设置完成后单击“关闭”按钮并退出整个 Visual Studio 2022，就完成了将开发环境设置为 C++ 语言的操作步骤。</p><p>Visual Studio 2022 会不定时更新，当需要更新时，在 Visual Studio 2022 界面上会有提示。单击提示会出现一些操作步骤，按照操作步骤进行操作就可以在线更新。值得一提的是，可能需要注册一个账号才能进行正常的在线更新，我们直接根据系统提示进行注册即可。</p><h2 id="创建最基本的能运行的-c-程序" tabindex="-1">创建最基本的能运行的 C++ 程序 <a class="header-anchor" href="#创建最基本的能运行的-c-程序" aria-label="Permalink to &quot;创建最基本的能运行的 C++ 程序&quot;">​</a></h2><p>安装好之后，为了后续做范例演示的方便，我们要做的第一件事就是创建一个最基本的能运行的 C++ 程序。</p><p>在 Visual Studio 2022 中，只需要点几下菜单，就能创建出一个最基本的能运行的 C++ 程序，其他的 Visual Studio 版本操作也类似，你可以参考下面的步骤。</p><ol><li><p>启动 Visual Studio 2022；</p></li><li><p>在启动界面，单击右下角“创建新项目”选项，会弹出如图 5 所示的对话框，选择“控制台应用”选项，并单击“下一步”按钮；</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/5.png" alt=""></a></p><ul><li>图5 Visual Studio 2022创建新项目</li></ul><ol start="3"><li>让系统新创建一个项目，请记住，Visual Studio 2022 中，任何一个可执行程序都是通过新建一个项目的方式得来，所以新建一个项目是必须的。在图 6 中，我们还需要填写一些项目的配置信息：项目名称、位置以及解决方案名称。</li></ol><p>项目名称：为创建的项目起的名字，例如输入 MyProject。</p><p>位置：保存此项目的位置，可以直接输入一个目录路径，或单击后面的“…”按钮，选择一个已存在的目录名，这里导航到事先创建好的路径：C:\\Users\\KuangXiang\\Desktop\\C++（可根据需要自由选择路径）。</p><p>解决方案名称：一个解决方案里可以包含多个项目，Visual Studio 开发环境硬性要求一个项目必须被包含在一个解决方案里。同时，一个项目最终可以生成一个可执行程序，所以创建MyProject 项目时，Visual Studio 2022 会连带创建一个解决方案，并让 MyProject 项目包含在该解决方案里。</p><p>解决方案名称这里输入 MySolution。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/6.png" alt=""></a></p><ul><li>图6 新项目的一些配置信息</li></ul><ol start="4"><li>单击图 6 右下角的 “创建”按钮，系统就会开始创建项目，几秒钟后，系统会创建好一个叫MyProject 的项目，正好位于 MySolution 解决方案之下。如图 7 所示。</li></ol><p>因版本不断升级变化，每个人看到的界面内容可能会略有差异，这不要紧，不过一定注意，不要随意改动内容，以免出错。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/7.png" alt=""></a></p><ul><li>图7 成功创建了一个新项目</li></ul><p>如果你使用的是其他 Visual Studio 版本，创建项目的步骤大同小异，只要能创建一个基于控制台的 C++ 程序项目供后续学习使用即可。如果不确定自己使用的 Visual Studio 版本如何创建项目，通过搜索引擎搜索诸如“Visual Studio 2022 创建新 C++ 项目”这样的关键词组合就能找到详细答案。</p><p>之后，展开图 7 左侧的“源文件”文件夹的树状分支，会发现其中包含一个 MyProject.cpp 文件。这是系统依据图 6 所起的项目名称生成的一个源码文件，里面已经包含一些 C++ 源码，其实目前系统生成的该项目已经能够编译并运行了。</p><p>项目要先编译、链接、生成可执行程序，然后才能运行。这一整套动作用快捷键 Ctrl+F5 就可以完成，该快捷键在很多 Visual Studio 版本中通用，记住它。如果出现一个提示窗口，可以按提示窗口中的 Yes，也可以直接按回车键进行确认。</p><p>如果按 Ctrl+F5 键之后 Visual Studio 2022 没任何反应，可能是这个快捷键被其他软件所占用，此时可以用 Visual Studio 2022 中的菜单命令代替，依次单击如图 8 所示的菜单命令“调试、开始执行（不调试）”命令也能达到编译、链接、生成可执行程序并开始执行的效果。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/8.png" alt=""></a></p><ul><li>图8 编译生成可执行程序并执行</li></ul><p>可执行程序运行起来后，出现一个背景为黑色的窗口，其中显示 Hello World 字符串如图 9 所示。</p><p>因为刚才创建项目时选择的是“控制台应用”，这种“控制台应用”项目运行后显示的正是一个黑色窗口，该窗口中会显示程序执行的结果，通过该窗口显示运行结果完全能够满足本课程的学习要求。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/9.png" alt=""></a></p><ul><li>图9 可执行程序的执行结果</li></ul><p>此时按任意键，黑窗口就会关闭。可执行程序执行结果中之所以会显示 Hello World！，是因为在 MyProject.cpp 源码文件中有如图 10 所示代码行的缘故，代码的含义属于 C++ 的基础开发知识，相信你一定非常熟悉，在这里就不多说了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/10.png" alt=""></a></p><ul><li>图10 输出语句std::cout向屏幕输出字符串Hello World</li></ul><h2 id="visual-studio-中程序的调试方法" tabindex="-1">Visual Studio 中程序的调试方法 <a class="header-anchor" href="#visual-studio-中程序的调试方法" aria-label="Permalink to &quot;Visual Studio 中程序的调试方法&quot;">​</a></h2><p>一切准备就绪后，我们讲述一下程序调试的方法，毕竟尤其是新手，在编写程序的过程中会经常犯错误，例如程序执行的效果并不是自己所期望的，程序运行崩溃，或者在阅读他人代码时要理清代码的执行流程等，都需要对程序进行调试。</p><h2 id="普通的断点调试-跟踪调试" tabindex="-1">普通的断点调试（跟踪调试） <a class="header-anchor" href="#普通的断点调试-跟踪调试" aria-label="Permalink to &quot;普通的断点调试（跟踪调试）&quot;">​</a></h2><p>首先，我介绍一下如何在 Visual Studio 2022（其他 Visual Studio 版本也类似）中进行程序的调试。</p><ol><li>快捷键 F9（对应菜单“调试→切换断点”），用于给光标所在的行增加断点（设置断点）或取消该行已有的断点，断点行最前面会有一个红色的小圆球表示该行有一个断点，如图 11 所示，可以通过将光标定位到多个行并每次都按 F9 来为多个行增加断点。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/11.png" alt=""></a></p><ul><li>图11 给某行增加断点后该行前面出现红色小圆球</li></ul><ol start="2"><li>快捷键 F5（对应菜单“调试→开始调试”），用于开始执行程序，遇到第一个断点行就停下来，如图 12 所示，程序停到了第 8 行，这个红色圆球中间多了一个向右指向的黄色小箭头，表示程序执行流程停止到了这一行（虽然停止到了这一行，但是此刻这一行还没有被执行，表示即将要执行）。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/12.png" alt=""></a></p><ul><li>图12 断点停止到了第8行</li></ul><ol start="3"><li><p>此时，因为程序执行流程已经停了下来，处于程序员（我们）的控制之中，所以就在此刻，可以多次使用快捷键 F10（对应菜单“调试→逐过程”），从当前停下来的这行开始，一行一行的执行下去，一边逐行执行，一边可以观察程序的执行走向（比如如果是条件语句就会因为不同的条件执行不同的分支）以及各种变量的值，从而达到调试的目的。</p></li><li><p>如果断点停在了一个自定义函数调用行，并且希望跟踪到这个函数里面的语句行中去，可以使用快捷键 F11（对应菜单“调试→逐语句”），跳入到函数中继续跟踪调试。如果想从当前所在的函数跳出去，可以使用快捷键 Shift+F11（对应菜单“调试→跳出”），就能够跳回到该函数的调用处并继续往下跟踪调试。</p></li></ol><h2 id="学会调试时查看内存中的内容" tabindex="-1">学会调试时查看内存中的内容 <a class="header-anchor" href="#学会调试时查看内存中的内容" aria-label="Permalink to &quot;学会调试时查看内存中的内容&quot;">​</a></h2><p>在程序调试的过程中，学会查看内存中的内容对于深入掌握 C/C++ 语言编程好处巨大。比如有时候需要看一看变量在内存中是如何存储的，或者某一块内存地址保存的是什么内容之类的问题，就都需要查看内存中的内容。</p><p>那么具体要怎么实现呢？</p><p>举个例子。下面是两行演示代码，按 F9 把断点设置到如下的 printf 行。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char aaa[1000] = &quot;safasdfa\\0def&quot;;</span></span>
<span class="line"><span>printf(aaa);</span></span></code></pre></div><p>按 F5 执行整个程序，使断点停在 printf 行上，那么此时此刻，就相当于处在了调试程序中，如图 13 所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/13.png" alt=""></a></p><ul><li>图13 正处于调试程序状态中</li></ul><p>在此种状态下，按下快捷键 alt+6 或者选择菜单“调试→窗口→内存→内存 1”，则在整个Visual Studio 2022 的下方，就打开了内存查看窗口，如图 14 所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/14.png" alt=""></a></p><ul><li>图14 在调试时可以打开调试窗口中的“内存”窗口来查看内存中的内容</li></ul><p>我们只需要在图 14 左上角位置“地址”右侧的编辑框中输入地址符 &amp;，后面跟要查看的变量名，然后按一下回车（比如这里输入 &amp;aaa 并按回车），就可以看该变量的地址所代表的内存中的内容了。</p><p>或者，在图 13 所示的第 78 行，双击选中 aaa 这个变量名，直接按住鼠标左键往图 14 中左上角位置“地址”右侧的编辑框中拖动并按回车，也能达到查看 aaa 变量所代表的内存中内容的目的，如图 15 所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/15.png" alt=""></a></p><ul><li>图15 变量aaa在内存中的内容</li></ul><p>图 15 所示的内存窗口中，左上角的“地址”部分显示的 0x00D3F288 是变量 aaa 所代表的内存地址。</p><p>往下看，分成三部分。</p><p>左侧部分显示的内存地址，是变量 aaa 的地址以及附近的内存地址。</p><p>中间部分显示的是内存地址中保存的十六进制数字内容。</p><p>没错，内存中保存的数据都是二进制数据，为了方便观察，Visual Studio 2022 中把这些二进制数据以十六进制形式显示出来，四位二进制数字显示为一位十六进制数字。</p><p>右侧部分显示的是内存中的十六进制数字所代表的一些字符，有些可显示字符会显示出来，对于不可显示的字符就用. 来代替。</p><p>程序代码中的“safasdfa\\0def”字样，与在中间的内存中的内容进行比较，可以看到，“\\0”这个转义字符在内存中显示的十六进制数字为 00，其它的字符比如“a”这个字符在内存中显示的十六进制数字为 61，十六进制的 61 正好是十进制的 97，而十进制的 97 正好就是字符“a”的ASCII 码。</p><p>所以，在内存中存放一个字符时，存放的其实就是该字符的 ASCII 码。</p><h2 id="快速监视窗口" tabindex="-1">快速监视窗口 <a class="header-anchor" href="#快速监视窗口" aria-label="Permalink to &quot;快速监视窗口&quot;">​</a></h2><p>最后，我们来说一下如何使用快速监视窗口。当运行着的程序停到断点处时，也可以按Shift+F9（对应菜单：调试→快速监视），并在其中输入要监视的变量内容，这样也是可以看到变量中所保存的数据的。</p><p>比如输入 &amp;aaa 并按回车，可以看到 aaa 的地址，地址中的内容也是清晰可见的，如图 16 所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/01/16.png" alt=""></a></p><ul><li>图16 快速监视窗口，用于快速查看变量的值、变量的地址等等</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>到这里，今天的内容就讲解的差不多了。我们来总结一下。</p><p>这节课，我们对 C++ 编程环境的搭建进行了详细讲解。主要包括 Visual Studio 2022 集成开发环境的详细安装步骤，在 Visual Studio 2022 集成开发环境中创建一个最基本的能够运行的C++ 程序的方法，以及在 Visual Studio 中程序的调试方法。</p><p>关于调试方法，有三个比较重要的方面。</p><ol><li><p>在某行增加断点并执行到断点行、逐行执行程序、跳入到函数中继续跟踪以及从函数中跳出来；</p></li><li><p>调试时在内存窗口查看内存中的内容；</p></li><li><p>利用快速监视窗口查看变量的地址、值等。</p></li></ol><p>C++ 编程环境虽然有很多，但对于初学者，编程环境的搭建和使用越简单越好。我不赞同在开始学习编程时花大量时间去学习诸如 GDB 这样的命令行调试工具，毕竟难以使用并且需要记忆很多命令。与此同时， 我们节省出精力来，去学习更重要的内容——C++ 程序的编写，不是更好嘛？</p><p>掌握了 Visual Studio 2022 中程序的调试方法，就可以在后面的学习中利用这些手段帮助自己快速地看懂别人所写的代码、快速地找到自己代码中存在的问题等，从而达到大幅度加速掌握新知识的效果。</p><p>从下个版块开始，我们就要真正进入到 C++ 数据结构与算法知识的学习中去了，我将讲解各种常用的数据结构和算法。在此之前，强烈建议你把 Visual Studio 开发环境搭建好，方便后续动手实践每节课所讲的内容，让我们的学习效果事半功倍。</p><h2 id="归纳思考" tabindex="-1">归纳思考 <a class="header-anchor" href="#归纳思考" aria-label="Permalink to &quot;归纳思考&quot;">​</a></h2><ol><li><p>Visual Studio 2022 集成开发环境中常用的快捷键有哪些？</p></li><li><p>如何在调试程序时观察变量的内容？</p></li><li><p>如何在调试程序时打开内存窗口以观察内存中的内容？</p></li></ol><p>欢迎你在留言区和我互动。如果觉得有所收获，也可以分享给更多的朋友一起学习。我们下一讲见！</p>`,111)])])}const g=e(s,[["render",l]]);export{h as __pageData,g as default};
